export function moduleOf(type){return {id:globalThis.crypto?.randomUUID?.()??`m-${Date.now()}-${Math.random().toString(36).slice(2)}`,type,...Object.fromEntries(['time','gas','lime','slag','kS','kH','heat','powder','powderTime','overhead'].map(k=>[k,META[type][k]])),desulf:false,powderEnabled:false,al:.8,siMn:0,feSi:0,wire:.4,oxygen:type==='AOD'?24.5:type==='VOD'?8:0,pressure:type==='RH'?133:66,L:150,changed:false};}
export function initialState(grade='Q355'){const g=GRADES[grade];return {version:1,grade,batch:100,initial:{...g.initial},targets:structuredClone(g.target),includeEAF:true,eafTime:39.7,modules:g.route.map(type=>{const m=moduleOf(type);if(grade==='GCr15'){if(type==='LF')m.time=60;if(type==='VD')m.time=25;if(type==='SOFT')m.time=25;}return m;}),selected:null,metric:'S',view:'builder',baseline:null};}
export const KEYS=['S','H','O','N','C'];
export const LABELS={S:'硫 S',H:'氢 H',O:'总氧 T.O',N:'氮 N',C:'碳 C'};
export function validate(s){const errors=[];if(!GRADES[s.grade])errors.push('钢种无效');if(!Number.isFinite(s.eafTime)||s.eafTime<0||s.eafTime>180)errors.push('电炉时间需在0–180 min之间');if(!Number.isFinite(s.batch)||s.batch<1||s.batch>500)errors.push('钢水量需在1–500 t之间');for(const k of KEYS)if(!Number.isFinite(s.initial[k])||s.initial[k]<0||s.initial[k]>(k==='C'?5:k==='H'?50:5000))errors.push(`${LABELS[k]}进站值超出范围`);if(s.modules.length>12)errors.push('流程最多支持12个模块');for(const m of s.modules){if(!META[m.type]){errors.push('设备类型无效');continue;}for(const k of ['time','gas','lime','slag','kS','kH','heat','powder','powderTime','overhead','al','siMn','feSi','wire','oxygen','pressure','L'])if(!Number.isFinite(m[k])||m[k]<0)errors.push(`${META[m.type].short}的参数${k}必须非负`);if(m.time>180||m.overhead>60||m.gas>(m.type==='AOD'?200000:3000)||m.lime>100||m.slag>100||m.powder>200||m.kS>1||m.kH>1||m.L>1000||m.oxygen>100||m.al>10||m.siMn>100||m.feSi>100||m.wire>5)errors.push(`${META[m.type].short}参数超过教学模型范围`);if(m.powderTime>m.time)errors.push('喷粉时间不能超过RH有效处理时间');if(m.heat>m.time)errors.push('通电时间不能超过LF有效处理时间');}return [...new Set(errors)];}
const approach=(x,eq,k,t)=>eq+(x-eq)*Math.exp(-Math.max(0,k)*t);
const remove=(x,eq,k,t)=>approach(x,Math.min(x,eq),k,t);
function phases(m){const t=m.time,tag='教学分段';if(m.type==='LF'){const h=Math.min(m.heat,t),r=Math.max(0,t-h);return [{name:'通电 / 化渣 / 吹氩',time:h,gas:h,note:tag},{name:'成分微调 / 渣钢反应',time:r,gas:r,note:tag}].filter(x=>x.time>0);}if(['VD','VOD','RH'].includes(m.type))return [{name:'抽真空与准备',time:m.overhead*5/7,gas:0,note:'估算；本段气量未计'},{name:m.type==='RH'?'循环处理（含喷粉段）':m.type==='VD'?'保压脱气':'真空吹氧',time:t,gas:t,note:m.type==='VD'?'时间参考P08；效果为估算':'教学工况'},{name:'破空 / 离站',time:m.overhead*2/7,gas:0,note:'估算；本段气量未计'}].filter(x=>x.time>0);if(m.type==='AOD')return [{name:'分阶段脱碳',time:t*.7,gas:t*.7,note:tag},{name:'还原 / 脱硫 / 调整',time:t*.3,gas:t*.3,note:tag}];return [{name:META[m.type].short,time:t,gas:m.gas?t:0,note:tag}];}
export function simulate(s){const errors=validate(s);if(errors.length)return {errors};const batch=s.batch,steelKg=batch*1000,initial={...s.initial};let chem={...initial},slagKg=0,slagSkg=0,elapsed=s.includeEAF?s.eafTime:0;const rows=[],materials=[],points=[{name:'电炉出钢',time:elapsed,values:{...chem}}],notes=[];
 const add=(name,qty,unit,module,method,basis='教学设定')=>{if(qty>0)materials.push({name,qty,unit,module,method,basis});};
 if(s.includeEAF){rows.push({id:'eaf',name:'EAF 电炉初炼',start:0,end:elapsed,duration:elapsed,gasTime:null,powderTime:null,phases:[{name:'装料 / 熔化 / 初炼',time:elapsed,note:'时间由P02图注推算；入站成分从出钢开始'}],before:{...chem},after:{...chem},sDelta:0,hDelta:0,source:'P02',notes:['初炼成分采用输入值，不计算炉料到钢水的反应。']});add('石灰',38.1*batch,'kg','EAF','顶加 + 喷细料','P01：跨论文参考');add('轻烧白云石',25.4*batch,'kg','EAF','顶加','P01：跨论文参考');add('总碳料（含随料与喷吹）',14.7*batch,'kg','EAF','分配未报告','P01：跨论文参考');add('氧气',26.5*batch,'Nm³','EAF','吹入；时长未报告','P01：跨论文参考');}
 for(const m of s.modules){const meta=META[m.type],before={...chem},mn=[],stage=phases(m),duration=m.time+m.overhead,start=elapsed;let deS=false;slagKg+=(m.lime+m.slag)*batch;add('石灰',m.lime*batch,'kg',meta.short,'顶加');add('预熔精炼渣',m.slag*batch,'kg',meta.short,'顶加');
 const gasQuantity=m.gas*m.time/(m.type==='RH'?60:1000);add('氩气',gasQuantity,m.type==='RH'?'m³（原文口径）':'Nm³',meta.short,m.type==='RH'?'提升气':'底吹',m.type==='VD'?'P08流量；按本工况时长换算':m.type==='RH'?'P09流量；按本工况时长换算':'教学标准态设定');
 if(m.type==='LF'){if(m.al>0){chem.O=remove(chem.O,15,.10*m.al,m.time);add('铝（产品量）',m.al*batch,'kg','LF','顶加 / 脱氧');}add('硅锰',m.siMn*batch,'kg','LF','合金补加');add('硅铁',m.feSi*batch,'kg','LF','合金补加');deS=chem.O<=60&&slagKg>0;if(!deS)mn.push('脱硫受限：需足够脱氧与碱性精炼渣。');mn.push('T.O仅为夹杂物去除代理量，不能代替溶解氧定氧。');}
 if(m.type==='VD'){const pFactor=Math.min(1.5,Math.sqrt(66/Math.max(10,m.pressure)));const qFactor=Math.min(1.5,Math.sqrt(m.gas/260));chem.H=remove(chem.H,.5,m.kH*pFactor*qFactor,m.time);deS=m.desulf&&slagKg>0&&chem.O<=60;if(!m.desulf)mn.push('VD默认不直接脱硫：本段S保持不变。');else if(!deS)mn.push('协同脱硫未生效：需要前序脱氧和有效渣层。');else mn.push('VD协同脱硫为简化渣钢估算，不是抽真空直接去硫。');mn.push('脱氢速率常数为教学假设，未由P08拟合。');}
 if(m.type==='RH'){chem.H=remove(chem.H,.6,m.kH*Math.min(1.5,Math.sqrt(m.gas/90)),m.time);if(m.powderEnabled&&m.powder>0&&m.powderTime>0){const powderMass=m.powder*m.powderTime;add('脱硫粉（配方待定）',powderMass,'kg','RH','喷粉','P09输运工况，不含化学配方');add('氩气',36*m.powderTime/60,'m³（原文口径）','RH','喷粉载气','P09');slagKg+=powderMass;deS=chem.O<=60;mn.push('粉末去硫效果为额外教学假设；P09只验证输运。');}if(chem.C<.08)chem.C=remove(chem.C,.003,.07,m.time);mn.push('RH提升气保留原文体积口径，不与Nm³直接合并。');}
 if(['AOD','VOD'].includes(m.type)){add('氧气',m.oxygen*batch,'Nm³',meta.short,'吹氧','教学设定，非完整论文制度');const tc=m.type==='AOD'?m.time*.7:m.time;const goal=m.type==='AOD'?.015:.006;const kinetic=remove(chem.C,goal,m.type==='AOD'?.14:.10,tc);const carbonCapacity=m.oxygen*.8*(24/22.414)/10;chem.C=Math.max(kinetic,chem.C-carbonCapacity,Math.min(chem.C,goal));if(m.oxygen<=0)mn.push('未供氧，不计算吹氧脱碳。');if(m.type==='AOD'){chem.O=remove(chem.O,35,.1,m.time*.3);deS=slagKg>0&&chem.O<80;add('还原用硅铁',10*batch,'kg','AOD','顶加','教学设定');}else{chem.H=remove(chem.H,.5,m.kH*Math.min(1.5,Math.sqrt(m.gas/250)),m.time);}mn.push('未计算Cr氧化损失、Ni/Mo补加和耐材反应。');}
 if(m.type==='SOFT'){chem.O=remove(chem.O,8,.045*Math.min(1.2,Math.sqrt(m.gas/50)),m.time);mn.push('只估算总氧代理量；未计算夹杂物尺寸和类型。');}
 if(m.type==='CA'){add('钙包芯线（整线质量）',m.wire*batch,'kg','喂线','喂线');mn.push('钙处理只提示夹杂改性，不按加线量扣减S或T.O。');}
 if(deS&&slagKg>0){const eq=(chem.S/1e6*steelKg+slagSkg)/(steelKg+m.L*slagKg)*1e6;const qFactor=m.type==='LF'?Math.min(1.5,Math.sqrt(m.gas/400)):1;const out=approach(chem.S,eq,m.kS*qFactor,m.type==='RH'?m.powderTime:m.type==='AOD'?m.time*.3:m.time);const transfer=(chem.S-out)/1e6*steelKg;chem.S=out;slagSkg+=transfer;}
 elapsed+=duration;const row={id:m.id,type:m.type,name:meta.name,start,end:elapsed,duration,gasTime:m.gas?m.time:0,powderTime:m.type==='RH'&&m.powderEnabled?m.powderTime:0,phases:stage,before,after:{...chem},sDelta:before.S-chem.S,hDelta:before.H-chem.H,source:meta.source,notes:mn};rows.push(row);points.push({name:meta.short,time:elapsed,values:{...chem}});notes.push(...mn);}
 const agg=new Map();for(const a of materials){const key=a.name+'|'+a.unit;const old=agg.get(key);if(old){old.qty+=a.qty;old.modules.add(a.module);old.methods.add(a.method);old.bases.add(a.basis);}else agg.set(key,{...a,modules:new Set([a.module]),methods:new Set([a.method]),bases:new Set([a.basis])});}const totals=[...agg.values()].map(a=>({...a,perTon:a.qty/batch,modules:[...a.modules],methods:[...a.methods],bases:[...a.bases]}));
 return {errors:[],initial,final:chem,rows,points,materials,totals,time:elapsed,solidKg:materials.filter(x=>x.unit==='kg').reduce((v,x)=>v+x.qty,0),argon:materials.filter(x=>x.name==='氩气'&&x.unit==='Nm³').reduce((v,x)=>v+x.qty,0),rawArgon:materials.filter(x=>x.name==='氩气'&&x.unit!=='Nm³').reduce((v,x)=>v+x.qty,0),notes:[...new Set(notes)],slagKg,slagSkg};}
export function meets(value,target){return Array.isArray(target)?value>=target[0]&&value<=target[1]:value<=target;}
export function assess(s,r){return KEYS.map(k=>({key:k,value:r.final[k],target:s.targets[k],ok:meets(r.final[k],s.targets[k])}));}
